from pathlib import Path
import shutil
root=Path('work/fire-site')
p=root/'app/layout.tsx';s=p.read_text();s=s.replace("title: 'Untitled site'","title: '소방공간뷰 · 건물 히스토리', description: '도면 업로드와 건물별 3D 검토 작업공간'").replace('lang="en"','lang="ko"');p.write_text(s,encoding='utf-8')
p=root/'app/page.tsx';s=p.read_text(encoding='utf-8')
s=s.replace("setBusy(true);setProgress(0);", "if(files.length>50||files.some(f=>f.size>20*1024*1024||!/\\.(pdf|png|jpe?g|bmp|webp)$/i.test(f.name))){setMessage('PDF·이미지를 최대 50개, 파일당 20MB까지 선택하세요.');return}let jobId='';setBusy(true);setProgress(0);")
s=s.replace('const {id}=await r.json();for','const {id}=await r.json();jobId=id;for')
s=s.replace('}catch(e){setMessage',"}catch(e){if(jobId)await fetch(`/api/buildings/${jobId}/failed`,{method:'POST'}).catch(()=>{});setMessage")
s=s.replace("i.status==='review'?'검토 필요':'작업 중'","i.status==='review'?'검토 필요':i.status==='failed'?'처리 중단':'작업 중'")
s=s.replace('다시 이어서 작업하세요.','필요할 때 다시 조회하세요.')
s=s.replace("useEffect(()=>{refresh()},[]);", '''useEffect(()=>{refresh();const context=(document as unknown as {modelContext?:{registerTool:(t:unknown,o:unknown)=>Promise<void>}}).modelContext;if(!context)return;const lifecycle=new AbortController();void Promise.resolve(context.registerTool({name:'list_building_history',description:'저장된 건물 작업과 처리 상태를 조회합니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>{const r=await fetch('/api/buildings');if(!r.ok)throw Error('목록 조회 실패');return r.json()}},{signal:lifecycle.signal})).catch(()=>{});return()=>lifecycle.abort()},[]);''')
s=s.replace('<p className="note">{i.note', '<details className="originals"><summary onClick={async e=>{const box=e.currentTarget.parentElement!;if(box.dataset.loaded)return;const r=await fetch(`/api/buildings/${i.id}/files`);if(!r.ok)return;const fs=await r.json();for(const f of fs){const a=document.createElement(\'a\');a.href=`/api/buildings/${i.id}/source/${f.id}`;a.textContent=f.name;a.style.display=\'block\';a.style.overflowWrap=\'anywhere\';box.append(a)}box.dataset.loaded=\'true\'}}>원본 파일</summary></details><p className="note">{i.note')
p.write_text(s,encoding='utf-8')
# Add touch gestures to the reviewed viewer without changing its original desktop source.
p=root/'public/models/industrial.html';s=p.read_text(encoding='utf-8')
touch='''<script>
window.addEventListener('load',()=>{const boot=setInterval(()=>{const v=window.industrialViewer,c=document.getElementById('canvas');if(!v||!c)return;clearInterval(boot);const touches=new Map();let gesture=null,suppress=false;const read=()=>{const a=[...touches.values()];return {x:(a[0].x+a[1].x)/2,y:(a[0].y+a[1].y)/2,d:Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)}};c.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch')return;touches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(touches.size===2){gesture=read();suppress=true;e.stopImmediatePropagation()}},true);c.addEventListener('pointermove',e=>{if(e.pointerType!=='touch')return;if(touches.has(e.pointerId))touches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(touches.size===2){const n=read(),r=v.state.radius;if(gesture&&n.d>1){v.state.radius=Math.max(8,Math.min(260,r*gesture.d/n.d));const m=v.camera.matrix.elements,dx=(n.x-gesture.x)*r*.0012,dy=(n.y-gesture.y)*r*.0012;v.state.target.x+=-m[0]*dx+m[4]*dy;v.state.target.y+=-m[1]*dx+m[5]*dy;v.state.target.z+=-m[2]*dx+m[6]*dy;c.dispatchEvent(new WheelEvent('wheel',{deltaY:0,cancelable:true}))}gesture=n;e.stopImmediatePropagation()}else if(suppress)e.stopImmediatePropagation()},true);const end=e=>{if(e.pointerType!=='touch')return;touches.delete(e.pointerId);if(suppress){e.stopImmediatePropagation();if(!touches.size){suppress=false;gesture=null;c.dispatchEvent(new PointerEvent('pointercancel'))}}};c.addEventListener('pointerup',end,true);c.addEventListener('pointercancel',end,true);const b=document.createElement('button');b.textContent='설정';b.className='tablet-toggle';b.onclick=()=>document.body.classList.toggle('show-controls');document.body.append(b)},100);setTimeout(()=>clearInterval(boot),20000)});
</script><style>.tablet-toggle{display:none}@media(max-width:1000px){main{grid-template-columns:1fr}aside{display:none;position:absolute;top:68px;bottom:0;left:0;width:260px;z-index:30;background:#14202e}.show-controls aside{display:block}.tablet-toggle{display:block;position:absolute;bottom:18px;right:18px;z-index:40;min-height:44px}button{min-height:44px}header h1{font-size:15px}.bottom{right:85px}.bottom span:last-child{display:none}}</style>'''
s=s.replace('</body>',touch+'</body>') if '</body>' in s else s.replace('</html>',touch+'</html>')
p.write_text(s,encoding='utf-8')
with (root/'app/globals.css').open('a',encoding='utf-8') as f:f.write('\n.originals{font-size:14px;color:#a6c9ec;margin-top:12px}.originals summary{cursor:pointer}.originals a{padding:7px 0}\n')
